@Component("shipment-handler")
@ProcessingGroup("shipment-processing-group")
public class ShipmentEventHandler {
	
	// core constructor
	ShipmentEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateShipmentEvent
     */
    @EventHandler
    public void handle( CreateShipmentEvent event) {
        entityManager.persist(new Shipment(event.getShipmentId(), event.getShipmentNumber(), event.getShippedDate(), event.getDeliveredDate(), event.getTrackingNumber(), event.getShippingAddress(), event.getOrder(), event.getShipmentItems(), event.getFulfillmentCenter(), event.getStatus(), event.getCarrier()));
    }

    /*
     * @param	event UpdateShipmentEvent
     */
    @EventHandler
    public Shipment handle( UpdateShipmentEvent event) {
    	entityManager.merge(new Shipment(event.getShipmentId(), event.getShipmentNumber(), event.getShippedDate(), event.getDeliveredDate(), event.getTrackingNumber(), event.getShippingAddress(), event.getOrder(), event.getShipmentItems(), event.getFulfillmentCenter(), event.getStatus(), event.getCarrier()));
    }
    
    /*
     * @param	event DeleteShipmentEvent
     */
    @EventHandler
    public void on( DeleteShipmentEvent event) {
    	Shipment entity = new Shipment();
   
    	// ------------------------------------------
    	// apply the ShipmentId
    	// ------------------------------------------
    	entity.setShipmentId( event.getShipmentId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final ShipmentRepository shipmentEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(ShipmentEventHandler.class.getName());

}
